import { execution } from '@dynatrace-sdk/automation-utils';

const MONTHLY_BUDGET      = 30000;  // configure: monthly cost cap in account currency

// ── Budget check ─────────────────────────────────────────────────────────────

function computeBudget(total) {
  const pct = Math.round((total / MONTHLY_BUDGET) * 10000) / 100;
  return { pct };
}


// ── Email formatting ──────────────────────────────────────────────────────────

function fmt(value, currency) {
  return `${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${currency}`;
}

function formatEmail(data, budget) {
  const { byCapability, byEnvironment, total, currency, subscriptionName, month, startLabel, endLabel } = data;
  const { pct, status } = budget;

  const capLines = Object.values(byCapability)
    .map(({ capabilityName, value }) => `  ${fmt(value, currency).padStart(18)}  ${capabilityName}`)
    .join('\n');

  const envLines = Object.entries(byEnvironment)
    .map(([envId, { total: t }]) => `  ${fmt(t, currency).padStart(18)}  ${envId}`)
    .join('\n');

  const subject = `DPS Cost Summary ${month} — ${fmt(total, currency)}`;

  const body = `DPS Monthly Cost Summary — Budget Alert from Workflow — ${month}
${'─'.repeat(52)}
Subscription : ${subscriptionName}
Period       : ${startLabel}  to  ${endLabel}

MONTHLY TOTAL
  ${fmt(total, currency)}  
  ${pct.toFixed(1)}% of ${fmt(MONTHLY_BUDGET, currency)} budget

BY ENVIRONMENT
${envLines}

─────────────────────────────────────────────────────
For detailed drill downs you can use Dynatrace Assist, our ready-made usage dashboards and Account Management.

─────────────────────────────────────────────────────
This report was generated automatically by the DPS Budget Tracker workflow.
For questions contact your Dynatrace account team.`;

  return { subject, body };
}


// ── Entry point ───────────────────────────────────────────────────────────────

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const data = await ex.result('get_monthly_cost_data_overview');

  const budget = computeBudget(data.total);
  console.log(`${data.total} ${data.currency} — ${budget.pct.toFixed(1)}% of budget (${budget.status})`);

  const { subject, body } = formatEmail(data, budget);

  return {
    budgetPct: budget.pct,
    subject,
    body,
  };
}

import { credentialVaultClient } from "@dynatrace-sdk/client-classic-environment-v2";

const TOKEN_URL       = 'https://sso.dynatrace.com/sso/oauth2/token';
const BASE_URL        = 'https://api.dynatrace.com';
const CREDENTIAL_NAME = 'DPS Budget Tracker OAuth';


// ── Auth ──────────────────────────────────────────────────────────────────────

function parseCredentials(username, password) {
  const lastDot = password.lastIndexOf('.');
  return {
    accountUuid: username,
    clientId: password.substring(0, lastDot),
    clientSecret: password,
  };
}

async function getOAuthToken(clientId, clientSecret, accountUuid) {
  const resp = await fetch(TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'client_credentials',
      client_id: clientId,
      client_secret: clientSecret,
      scope: 'account-uac-read',
      resource: `urn:dtaccount:${accountUuid}`,
    }),
  });
  if (!resp.ok) {
    const err = await resp.json().catch(() => ({}));
    throw new Error(`Token request failed (${resp.status}): ${err.error_description || err.error || 'unknown'}`);
  }
  return (await resp.json()).access_token;
}


// ── API ───────────────────────────────────────────────────────────────────────

const RETRY_STATUSES = new Set([429, 500, 502, 503, 504]);
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

async function apiGet(url, token, params = {}) {
  const qs = new URLSearchParams(params).toString();
  const fullUrl = qs ? `${url}?${qs}` : url;

  for (let attempt = 0; attempt < 3; attempt++) {
    const resp = await fetch(fullUrl, { headers: { Authorization: `Bearer ${token}` } });
    if (resp.ok) return resp.json();
    if (!RETRY_STATUSES.has(resp.status) || attempt === 2) {
      throw new Error(`GET ${url} failed (${resp.status}): ${await resp.text()}`);
    }
    await sleep(2 ** attempt * 1000);
  }
}

async function getActiveSubscription(token, accountUuid) {
  const data = await apiGet(`${BASE_URL}/sub/v2/accounts/${accountUuid}/subscriptions`, token);
  const active = (data.data || []).filter(s => s.status === 'ACTIVE' && s.type === 'REGULAR');
  if (active.length === 0) throw new Error('No active REGULAR subscription found.');
  return active[0];
}

async function getCostPerEnvironment(token, accountUuid, subscriptionUuid, startTime, endTime) {
  const url = `${BASE_URL}/sub/v3/accounts/${accountUuid}/subscriptions/${subscriptionUuid}/environments/cost`;
  let params = { startTime, endTime };
  const results = [];
  while (true) {
    const body = await apiGet(url, token, params);
    results.push(...(body.data || []));
    if (!body.nextPageKey) break;
    params = { ...params, 'page-key': body.nextPageKey };
  }
  return results;
}


// ── Time range ────────────────────────────────────────────────────────────────

function currentMonthRange() {
  const now = new Date();
  const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
  const yesterday = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - 1, 23, 59, 59));
  const fmt = d => d.toISOString().replace('.000Z', 'Z');
  return {
    start: fmt(start),
    end: fmt(yesterday),
    month: start.toISOString().substring(0, 7),
    startLabel: start.toISOString().substring(0, 10),
    endLabel: yesterday.toISOString().substring(0, 10),
  };
}


// ── Aggregation ───────────────────────────────────────────────────────────────

function aggregate(costPerEnv) {
  const byCapability = {};
  const byEnvironment = {};
  let currency = 'USD';
  const round = v => Math.round(v * 1e6) / 1e6;

  for (const env of costPerEnv) {
    const envId = env.environmentId || env.clusterId || 'unknown';
    if (!byEnvironment[envId]) byEnvironment[envId] = { total: 0 };

    for (const { capabilityName, capabilityKey, value, currencyCode } of env.cost || []) {
      currency = currencyCode || currency;
      if (!byCapability[capabilityKey]) byCapability[capabilityKey] = { capabilityName, value: 0 };
      byCapability[capabilityKey].value += value;
      byEnvironment[envId].total += value;
    }
  }

  for (const key of Object.keys(byCapability))  byCapability[key].value   = round(byCapability[key].value);
  for (const id  of Object.keys(byEnvironment)) byEnvironment[id].total   = round(byEnvironment[id].total);

  const total = round(Object.values(byCapability).reduce((s, c) => s + c.value, 0));

  // sort descending by value for readability in the email action
  const byCapabilitySorted = Object.fromEntries(
    Object.entries(byCapability).sort((a, b) => b[1].value - a[1].value)
  );
  const byEnvironmentSorted = Object.fromEntries(
    Object.entries(byEnvironment).sort((a, b) => b[1].total - a[1].total)
  );

  return { byCapability: byCapabilitySorted, byEnvironment: byEnvironmentSorted, total, currency };
}


// ── Entry point ───────────────────────────────────────────────────────────────

export default async function ({ executionId }) {
  const credList = await credentialVaultClient.listCredentials({ name: `"${CREDENTIAL_NAME}"` });
  if (!credList || credList.totalCount === 0) {
    throw new Error(`Credential "${CREDENTIAL_NAME}" not found.`);
  }
  const creds = await credentialVaultClient.getCredentialsDetails({ id: credList.credentials[0].id });
  const { accountUuid, clientId, clientSecret } = parseCredentials(creds.username, creds.password);

  const token = await getOAuthToken(clientId, clientSecret, accountUuid);
  const subscription = await getActiveSubscription(token, accountUuid);

  const range = currentMonthRange();
  console.log(`Fetching monthly costs for ${range.month} (${range.startLabel} to ${range.endLabel})`);

  const costPerEnv = await getCostPerEnvironment(token, accountUuid, subscription.uuid, range.start, range.end);
  const summary = aggregate(costPerEnv);

  console.log(`Total: ${summary.total} ${summary.currency}`);

  return {
    month: range.month,
    startLabel: range.startLabel,
    endLabel: range.endLabel,
    subscriptionName: subscription.name,
    total: summary.total,
    currency: summary.currency,
    byCapability: summary.byCapability,
    byEnvironment: summary.byEnvironment,
  };
}
